1	/**
2	 * Command-line interface for LCS computation.
3	 */
4	class LongestCommonSubsequenceCli {
5	    private static final LcsSolver solver = new StandardLcsSolver();
6	
7	    /**
8	     * Main entry point for CLI.
9	     * Usage: java LongestCommonSubsequenceCli [string1] [string2]
10	     * If no arguments provided, runs with example data.
11	     *
12	     * @param args command line arguments (optional)
13	     */
14	    public static void main(String[] args) {
15	        String s1;
16	        String s2;
17	
18	        if (args.length == 2) {
19	            s1 = args[0];
20	            s2 = args[1];
21	        } else if (args.length == 0) {
22	            s1 = "AGGTAB";
23	            s2 = "GXTXAYB";
24	            System.out.println("Running with default examples (no arguments provided).");
25	            System.out.println("Usage: java LongestCommonSubsequenceCli <string1> <string2>\n");
26	        } else {
27	            System.err.println("Invalid arguments. Expected 0 or 2 arguments.");
28	            System.err.println("Usage: java LongestCommonSubsequenceCli [string1] [string2]");
29	            System.exit(1);
30	            return;
31	        }
32	
33	        try {
34	            LcsInput input = new LcsInput(s1, s2);
35	            LcsResult result = solver.solve(input);
36	
37	            System.out.println("String 1: \"" + s1 + "\"");
38	            System.out.println("String 2: \"" + s2 + "\"");
39	            System.out.println("LCS Length: " + result.getLength());
40	        } catch (IllegalArgumentException e) {
41	            System.err.println("Error: " + e.getMessage());
42	            System.exit(1);
43	        }
44	    }
45	}
