1	/**
2	 * Strategy interface for character comparison in LCS computation.
3	 * Enables pluggable matching logic (case-sensitive, case-insensitive, custom rules).
4	 */
5	interface CharacterMatcher {
6	    /**
7	     * Determines if two characters match according to the matching strategy.
8	     *
9	     * @param a first character
10	     * @param b second character
11	     * @return true if characters match, false otherwise
12	     */
13	    boolean matches(char a, char b);
14	}
15	
16	/**
17	 * Standard case-sensitive character matching.
18	 */
19	class StandardCharacterMatcher implements CharacterMatcher {
20	    @Override
21	    public boolean matches(char a, char b) {
22	        return a == b;
23	    }
24	}
25	
26	/**
27	 * Case-insensitive character matching.
28	 * Treats uppercase and lowercase versions of the same letter as matching.
29	 */
30	class CaseInsensitiveCharacterMatcher implements CharacterMatcher {
31	    @Override
32	    public boolean matches(char a, char b) {
33	        return Character.toLowerCase(a) == Character.toLowerCase(b);
34	    }
35	}
36	
37	/**
38	 * Whitespace-insensitive matching.
39	 * Ignores differences in whitespace characters.
40	 */
41	class WhitespaceInsensitiveMatcher implements CharacterMatcher {
42	    @Override
43	    public boolean matches(char a, char b) {
44	        boolean aIsSpace = Character.isWhitespace(a);
45	        boolean bIsSpace = Character.isWhitespace(b);
46	
47	        if (aIsSpace && bIsSpace) {
48	            return true;
49	        }
50	        if (aIsSpace || bIsSpace) {
51	            return false;
52	        }
53	        return a == b;
54	    }
55	}
