1	/**
2	 * Shared test data for LCS solver testing.
3	 * Centralizes test case definitions to avoid duplication across test classes
4	 * and enable consistent testing of all solver implementations.
5	 */
6	class TestData {
7	
8	    /**
9	     * Standard test cases covering common scenarios.
10	     * Format: {string1, string2, expected_lcs_length}
11	     */
12	    static final Object[][] STANDARD_CASES = {
13	        {"AGGTAB", "GXTXAYB", 4},
14	        {"", "", 0},
15	        {"ABC", "DEF", 0},
16	        {"ABCDEF", "ABCDEF", 6},
17	        {"AAAA", "AA", 2},
18	        {"ABCDE", "XBYDZ", 2},
19	        {"LONGSTRING", "SHORT", 2},
20	        {"A", "A", 1},
21	        {"A", "B", 0},
22	    };
23	
24	    /**
25	     * Edge cases covering boundary conditions.
26	     * Format: {string1, string2, expected_lcs_length}
27	     */
28	    static final Object[][] EDGE_CASES = {
29	        {"", "", 0},                    // Both empty
30	        {"", "ABC", 0},                 // First empty
31	        {"ABC", "", 0},                 // Second empty
32	        {"A", "A", 1},                  // Single matching char
33	        {"A", "B", 0},                  // Single non-matching
34	    };
35	
36	    /**
37	     * Special character test cases.
38	     * Format: {string1, string2, expected_lcs_length}
39	     */
40	    static final Object[][] SPECIAL_CASES = {
41	        {"A@B#C", "A$B%C", 3},          // Special chars (A,B,C match)
42	        {"A B C", "ABC", 3},            // Whitespace (A,B,C match)
43	        {"12345", "13579", 3},          // Numbers (1,3,5 match)
44	        {"café", "cáfé", 4},            // Accented characters
45	    };
46	
47	    /**
48	     * Test case object combining input strings and expected result.
49	     */
50	    static class TestCase {
51	        final String s1;
52	        final String s2;
53	        final int expectedLength;
54	
55	        TestCase(String s1, String s2, int expectedLength) {
56	            this.s1 = s1;
57	            this.s2 = s2;
58	            this.expectedLength = expectedLength;
59	        }
60	
61	        @Override
62	        public String toString() {
63	            return String.format("TestCase(\"%s\", \"%s\", expect %d)",
64	                    s1, s2, expectedLength);
65	        }
66	    }
67	
68	    /**
69	     * Converts raw test data arrays to TestCase objects.
70	     *
71	     * @param rawData array of {string1, string2, expectedLength} arrays
72	     * @return TestCase objects
73	     */
74	    static TestCase[] toTestCases(Object[][] rawData) {
75	        TestCase[] cases = new TestCase[rawData.length];
76	        for (int i = 0; i < rawData.length; i++) {
77	            cases[i] = new TestCase(
78	                    (String) rawData[i][0],
79	                    (String) rawData[i][1],
80	                    (int) rawData[i][2]
81	            );
82	        }
83	        return cases;
84	    }
85	
86	    /**
87	     * Test cases for reconstruction (expecting specific LCS strings).
88	     * Format: {string1, string2, expected_lcs_string}
89	     */
90	    static class ReconstructionCase {
91	        final String s1;
92	        final String s2;
93	        final String expectedLcs;
94	
95	        ReconstructionCase(String s1, String s2, String expectedLcs) {
96	            this.s1 = s1;
97	            this.s2 = s2;
98	            this.expectedLcs = expectedLcs;
99	        }
100	
101	        @Override
102	        public String toString() {
103	            return String.format("ReconstructionCase(\"%s\", \"%s\", expect \"%s\")",
104	                    s1, s2, expectedLcs);
105	        }
106	    }
107	
108	    static final ReconstructionCase[] RECONSTRUCTION_CASES = {
109	        new ReconstructionCase("AGGTAB", "GXTXAYB", "GTAB"),
110	        new ReconstructionCase("", "", ""),
111	        new ReconstructionCase("ABC", "DEF", ""),
112	        new ReconstructionCase("ABCDEF", "ABCDEF", "ABCDEF"),
113	        new ReconstructionCase("AAAA", "AA", "AA"),
114	        new ReconstructionCase("ABCDE", "XBYDZ", "BD"),
115	    };
116	
117	    /**
118	     * Performance test cases with larger strings.
119	     */
120	    static class PerformanceCase {
121	        final String s1;
122	        final String s2;
123	        final int maxExpectedTimeMs;
124	
125	        PerformanceCase(String s1, String s2, int maxExpectedTimeMs) {
126	            this.s1 = s1;
127	            this.s2 = s2;
128	            this.maxExpectedTimeMs = maxExpectedTimeMs;
129	        }
130	    }
131	
132	    static final PerformanceCase[] PERFORMANCE_CASES = {
133	        new PerformanceCase(generateString('A', 100), generateString('B', 100), 10),
134	        new PerformanceCase(generateString('A', 500), generateString('B', 500), 100),
